const expressionEl = document.getElementById('expression');
const resultEl = document.getElementById('result');

let current = '0';
let previous = '';
let operator = '';
let shouldReset = false;

function updateDisplay() {
  resultEl.textContent = current;
  expressionEl.textContent = previous + (operator ? ` ${operator}` : '');
}

function inputDigit(d) {
  if (shouldReset) { current = '0'; shouldReset = false; }
  if (current === '0' && d !== '.') current = d;
  else current += d;
  updateDisplay();
}

function inputDecimal() {
  if (shouldReset) { current = '0'; shouldReset = false; }
  if (!current.includes('.')) current += '.';
  updateDisplay();
}

function calculate(a, op, b) {
  a = parseFloat(a); b = parseFloat(b);
  switch (op) {
    case '+': return a + b;
    case '−': return a - b;
    case '×': return a * b;
    case '÷': return b === 0 ? 'Error' : a / b;
  }
}

function handleOperator(op) {
  if (operator && !shouldReset) {
    const res = calculate(previous, operator, current);
    if (res === 'Error') { current = 'Error'; previous = ''; operator = ''; updateDisplay(); return; }
    current = String(parseFloat(res.toFixed(10)));
    previous = current;
  } else {
    previous = current;
  }
  operator = op;
  shouldReset = true;
  updateDisplay();
}

function handleEquals() {
  if (!operator) return;
  const res = calculate(previous, operator, current);
  current = res === 'Error' ? 'Error' : String(parseFloat(parseFloat(res).toFixed(10)));
  previous = '';
  operator = '';
  shouldReset = true;
  updateDisplay();
}

function clear() {
  current = '0'; previous = ''; operator = ''; shouldReset = false;
  updateDisplay();
}

document.querySelector('.buttons').addEventListener('click', e => {
  const btn = e.target.closest('.btn');
  if (!btn) return;
  if (current === 'Error' && btn.dataset.action !== 'clear') clear();

  switch (btn.dataset.action) {
    case 'digit': inputDigit(btn.dataset.value); break;
    case 'decimal': inputDecimal(); break;
    case 'operator': handleOperator(btn.dataset.value); break;
    case 'equals': handleEquals(); break;
    case 'clear': clear(); break;
    case 'negate':
      if (current !== '0') current = current.startsWith('-') ? current.slice(1) : '-' + current;
      updateDisplay(); break;
    case 'percent':
      current = String(parseFloat(current) / 100);
      updateDisplay(); break;
  }
});

// Keyboard support
document.addEventListener('keydown', e => {
  if (e.key >= '0' && e.key <= '9') inputDigit(e.key);
  else if (e.key === '.') inputDecimal();
  else if (e.key === '+') handleOperator('+');
  else if (e.key === '-') handleOperator('−');
  else if (e.key === '*') handleOperator('×');
  else if (e.key === '/') { e.preventDefault(); handleOperator('÷'); }
  else if (e.key === 'Enter' || e.key === '=') handleEquals();
  else if (e.key === 'Escape') clear();
  else if (e.key === 'Backspace') { current = current.slice(0, -1) || '0'; updateDisplay(); }
});

