"""
Comprehensive unit tests for the calculator module.

Tests cover:
- Basic arithmetic operations (add, subtract, multiply, divide)
- Edge cases: division by zero, negative numbers, large numbers
- Error handling and boundary values
- Floating-point precision
"""

import pytest
import sys
import os

# Add calculator module to path
sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "calculator"))

from calculator import add, subtract, multiply, divide


# ---------------------------------------------------------------------------
# Addition
# ---------------------------------------------------------------------------

class TestAddition:
    def test_positive_integers(self):
        assert add(2, 3) == 5

    def test_negative_integers(self):
        assert add(-2, -3) == -5

    def test_mixed_signs(self):
        assert add(-2, 3) == 1
        assert add(2, -3) == -1

    def test_zero(self):
        assert add(0, 0) == 0
        assert add(5, 0) == 5
        assert add(0, 5) == 5

    def test_floats(self):
        assert add(0.1, 0.2) == pytest.approx(0.3)
        assert add(1.5, 2.5) == 4.0

    def test_large_numbers(self):
        assert add(10**15, 10**15) == 2 * 10**15

    def test_very_small_floats(self):
        result = add(1e-10, 1e-10)
        assert result == pytest.approx(2e-10)


# ---------------------------------------------------------------------------
# Subtraction
# ---------------------------------------------------------------------------

class TestSubtraction:
    def test_positive_integers(self):
        assert subtract(5, 3) == 2

    def test_negative_result(self):
        assert subtract(3, 5) == -2

    def test_negative_inputs(self):
        assert subtract(-3, -5) == 2
        assert subtract(-5, -3) == -2

    def test_subtract_zero(self):
        assert subtract(5, 0) == 5
        assert subtract(0, 5) == -5

    def test_same_value(self):
        assert subtract(7, 7) == 0

    def test_floats(self):
        assert subtract(3.5, 1.2) == pytest.approx(2.3)

    def test_large_numbers(self):
        assert subtract(10**15, 1) == 10**15 - 1


# ---------------------------------------------------------------------------
# Multiplication
# ---------------------------------------------------------------------------

class TestMultiplication:
    def test_positive_integers(self):
        assert multiply(3, 4) == 12

    def test_negative_by_positive(self):
        assert multiply(-3, 4) == -12

    def test_negative_by_negative(self):
        assert multiply(-3, -4) == 12

    def test_multiply_by_zero(self):
        assert multiply(0, 5) == 0
        assert multiply(5, 0) == 0
        assert multiply(0, 0) == 0

    def test_multiply_by_one(self):
        assert multiply(42, 1) == 42
        assert multiply(1, 42) == 42

    def test_floats(self):
        assert multiply(2.5, 4.0) == pytest.approx(10.0)
        assert multiply(0.1, 0.1) == pytest.approx(0.01)

    def test_large_numbers(self):
        assert multiply(10**7, 10**7) == 10**14

    def test_fractional_results(self):
        assert multiply(1, 3) == pytest.approx(3.0)
        assert multiply(1.0, 3.0) == pytest.approx(3.0)


# ---------------------------------------------------------------------------
# Division
# ---------------------------------------------------------------------------

class TestDivision:
    def test_positive_integers(self):
        assert divide(10, 2) == 5

    def test_negative_dividend(self):
        assert divide(-10, 2) == -5

    def test_negative_divisor(self):
        assert divide(10, -2) == -5

    def test_both_negative(self):
        assert divide(-10, -2) == 5

    def test_floats(self):
        assert divide(7.5, 2.5) == pytest.approx(3.0)

    def test_divide_by_one(self):
        assert divide(42, 1) == 42

    def test_divide_self(self):
        assert divide(7, 7) == pytest.approx(1.0)

    def test_fractional_result(self):
        assert divide(1, 3) == pytest.approx(1 / 3)

    def test_divide_zero_by_nonzero(self):
        assert divide(0, 5) == 0


# ---------------------------------------------------------------------------
# Division by Zero — Error Handling
# ---------------------------------------------------------------------------

class TestDivisionByZero:
    def test_divide_by_zero_raises(self):
        """Dividing by zero must raise ZeroDivisionError."""
        with pytest.raises(ZeroDivisionError):
            divide(10, 0)

    def test_negative_divided_by_zero_raises(self):
        with pytest.raises(ZeroDivisionError):
            divide(-10, 0)

    def test_zero_divided_by_zero_raises(self):
        with pytest.raises(ZeroDivisionError):
            divide(0, 0)

    def test_float_zero_divisor_raises(self):
        with pytest.raises(ZeroDivisionError):
            divide(5, 0.0)


# ---------------------------------------------------------------------------
# Type Errors
# ---------------------------------------------------------------------------

class TestTypeErrors:
    @pytest.mark.parametrize("a, b", [
        ("foo", 2),
        (2, "bar"),
        (None, 1),
        ([1], 2),
    ])
    def test_invalid_types(self, a, b):
        with pytest.raises(TypeError):
            add(a, b)


# ---------------------------------------------------------------------------
# Boundary / Edge Values
# ---------------------------------------------------------------------------

class TestBoundaryValues:
    def test_very_large_addition(self):
        result = add(1.7976931348623157e+308, 1e307)
        assert result == pytest.approx(float('inf'), abs=1e300)

    def test_very_small_subtraction(self):
        result = subtract(-1.7976931348623157e+308, 1e307)
        assert result == pytest.approx(float('-inf'), abs=1e300)

    def test_multiply_large_numbers_to_inf(self):
        result = multiply(1e200, 1e200)
        assert result == float('inf')

    def test_multiply_very_small_numbers_to_zero(self):
        result = multiply(1e-200, 1e-200)
        assert result == 0.0

    def test_divide_very_small_by_very_small(self):
        result = divide(1e-10, 1e-200)
        assert result == pytest.approx(1e190, rel=1e-5)

    def test_positive_infinity(self):
        assert add(float('inf'), 1) == float('inf')

    def test_negative_infinity(self):
        assert subtract(float('-inf'), 1) == float('-inf')

    def test_inf_division(self):
        assert divide(float('inf'), 2) == float('inf')
